/**
 * STARFORGED COMPANION
 * src/sectors/siteDiscovery.js — Reveal a precursor vault / derelict site.
 *
 * Sites generated by the sector creator start "unexplored": a dim pin behind an
 * undiscovered passage (see precursorSites.js / sceneBuilder.js). Discovery is
 * the payoff for reaching one — finishing an expedition toward it, or a manual
 * GM reveal (`!reveal-site`). Revealing flips the discovery record, marks the
 * location Actor visited, and re-styles the scene pin + passage to their charted
 * appearance.
 *
 * GM-gated by the caller (world-setting writes need GM). Dependency-injected so
 * the orchestration unit-tests without a live game.
 */

import { selectSectorSite } from "./precursorSites.js";
import { restyleSiteOnScene }  from "./sceneBuilder.js";
import { updateLocation, getLocation } from "../entities/location.js";
import { serialiseCampaignStateWrite } from "../multiplayer/campaignStateChain.js";

const MODULE_ID = "starforged-companion";

/**
 * A discovery record's site as the table knows it: its location Actor's
 * record name (kept in step with the Actor by the rename sync), else the
 * record's own — the generated name the record keeps. A site renamed by the
 * GM was named one way on the map and another in the narrator's Charted
 * sites and `!clear-site` (issue #326 W75).
 *
 * @param {{ name?: string, actorId?: string|null }} site
 * @returns {string}
 */
export function siteDisplayName(site) {
  if (site?.actorId) {
    try {
      const name = getLocation(site.actorId)?.name;
      if (typeof name === "string" && name.trim()) return name.trim();
    } catch (err) {
      console.debug?.(`${MODULE_ID} | site name lookup for ${site.actorId} failed:`, err?.message ?? err);
    }
  }
  return String(site?.name ?? "");
}

/**
 * The site an expedition is for: the discovery its track links (`siteId`),
 * charted or not, else the unexplored site its label names — exact, whole
 * words or the type keyword (`requireLabelMatch`: never the sole-site guess,
 * so an expedition to a settlement is for no site). Finishing the expedition
 * arrives there, by the site's location Actor: the crew names an unexplored
 * site in their own words (its pin reads "Unexplored Site"), so the label
 * alone resolved to no place — SHIP POSITION named a phrase, and the token and
 * CURRENT LOCATION stayed on the settlement they left (issue #342 Z14). A
 * read of the given state.
 *
 * @param {Object} state — campaignState (its `sectors`, `activeSectorId`)
 * @param {string|null} label — the expedition's label
 * @param {{ siteId?: string|null }} [opts] — the track's link
 * @returns {{ sector: Object, site: Object }|null}
 */
export function selectExpeditionSite(state, label, { siteId = null } = {}) {
  const sectors = Array.isArray(state?.sectors) ? state.sectors : [];
  if (siteId) {
    for (const sector of sectors) {
      const site = (sector?.mapData?.discoveries ?? []).find(d => d?.id === siteId);
      if (site) return { sector, site };
    }
  }
  return selectSectorSite(sectors, label, {
    requireLabelMatch: true,
    activeSectorId:    state?.activeSectorId ?? null,
    siteName:          siteDisplayName,
  });
}

/**
 * Reveal the first undiscovered site (across all stored sectors) matching a
 * destination label. Returns the revealed { sector, site } or null when nothing
 * matched. Persists campaign state only when a site is revealed.
 *
 * @param {string|null} label — expedition destination / command target
 * @param {Object} [opts]
 * @param {string}   [opts.source]    — telemetry tag ("expedition" | "manual")
 * @param {string}   [opts.siteId]    — a stored expedition→site link: reveal
 *   exactly this discovery when it exists, bypassing the name-fuzzy ladder
 *   (2026-07 soft-spot fix — with several undiscovered sites the ladder could
 *   reveal the "wrong" one). The ladder runs across every sector at once
 *   (selectSectorSite), so neither this id nor an exact name can be preempted
 *   by a guess in an earlier sector (issue #300 F07).
 * @param {boolean}  [opts.requireLabelMatch] — reveal only a site the link or
 *   the label names, never the sole-site guess: a Finish an Expedition's
 *   reveal (an expedition to a settlement charted the sector's last unexplored
 *   site — issue #342 D7). `!reveal-site` keeps the guess.
 * @param {Function} [opts.getState]  — () => campaignState
 * @param {Function} [opts.setState]  — (state) => Promise — the state with the
 *   flag set, a copy; the move pipeline's seam folds its sectors into the
 *   working copy its persist writes
 * @param {Function} [opts.getScene]  — (sceneId) => Scene|null
 * @param {Function} [opts.updateLoc] — (actorId, updates) => Promise
 * @param {Function} [opts.restyle]   — (scene, site) => Promise
 * @returns {Promise<{sector:Object, site:Object}|null>}
 */
export async function revealSectorSite(label, opts = {}) {
  const getState  = opts.getState  ?? storedState;
  const setState  = opts.setState  ?? null;   // the store, on the write chain
  const getScene  = opts.getScene  ?? (id => game.scenes?.get?.(id) ?? null);
  const updateLoc = opts.updateLoc ?? updateLocation;
  const restyle   = opts.restyle   ?? restyleSiteOnScene;

  const state = getState();
  const found = selectSectorSite(state?.sectors, label, {
    siteId:            opts.siteId ?? null,
    activeSectorId:    state?.activeSectorId ?? null,
    siteName:          siteDisplayName,
    requireLabelMatch: opts.requireLabelMatch === true,
  });
  if (!found) return null;
  const { sector, site: match } = found;

  // The flag is set on a copy: the record is the stored state's (the cached
  // setting, by default), and setting it in place before a refused write left
  // the site revealed on the GM's client alone — a retried !reveal-site found
  // "no matching unexplored site" (issue #326 W51; rules/foundry-api.md).
  const revealed = { ...match, discovered: true, name: siteDisplayName(match) };

  if (match.actorId) {
    try { await updateLoc(match.actorId, { status: "visited" }); }
    catch (err) { console.warn(`${MODULE_ID} | revealSectorSite: location status update failed:`, err?.message ?? err); }
  }

  if (sector.sceneId) {
    const scene = getScene(sector.sceneId);
    if (scene) {
      try { await restyle(scene, revealed); }
      catch (err) { console.warn(`${MODULE_ID} | revealSectorSite: scene restyle failed:`, err?.message ?? err); }
    }
  }

  await persistSiteFlag(getState, setState, sector, match, "discovered", "revealSectorSite");
  return { sector, site: revealed };
}

/**
 * Save a site's discovered flag on the latest stored campaignState — a move's
 * site reveal whose record the world refused, applied again from the GMs'
 * payoff failure card (issue #331 X18). The reveal's scene pin and location
 * status were applied at the reveal; only the flag rode on the move's record.
 *
 * @param {{ sectorId?: string|null, siteId?: string|null }} ref
 * @returns {Promise<{ ok: boolean, reason?: string, error?: string }>}
 */
export async function saveSiteDiscovered({ sectorId = null, siteId = null } = {}) {
  if (!sectorId || !siteId) return { ok: false, reason: "invalid step" };
  const sector = (storedState()?.sectors ?? []).find(s => s?.id === sectorId) ?? null;
  const site   = sector?.mapData?.discoveries?.find?.(d => d?.id === siteId) ?? null;
  if (!site) return { ok: false, reason: "site-gone" };
  if (site.discovered) return { ok: true };
  try {
    await persistSiteFlag(storedState, null, sector, site, "discovered", "saveSiteDiscovered");
    return { ok: true };
  } catch (err) {
    console.warn(`${MODULE_ID} | saveSiteDiscovered: the world refused the write:`, err?.message ?? err);
    return { ok: false, reason: "refused", error: String(err?.message ?? err) };
  }
}

/**
 * Post a GM/table-visible card announcing a newly discovered site.
 *
 * @param {{sector:Object, site:Object}} result — revealSectorSite() return
 * @returns {Promise<void>}
 */
export async function postSiteDiscoveryCard(result) {
  const site = result?.site;
  if (!site) return;
  const kind = site.type === "vault" ? "precursor vault" : "derelict";

  // Surface the rolled exterior at the payoff moment (SITE-DISCOVERY-CARD-
  // GENERIC fix, 2026-07): the map discovery record is deliberately light,
  // so read the location Actor's record for the first look. Fail-open — a
  // missing record just renders the original generic line.
  let firstLookLine = "";
  try {
    const record = site.actorId ? getLocation(site.actorId) : null;
    if (record?.firstLook) {
      firstLookLine = `<p><em>${escapeSiteHtml(record.firstLook)}</em></p>`;
    }
  } catch (err) {
    console.debug?.(`${MODULE_ID} | postSiteDiscoveryCard: record read failed:`, err?.message ?? err);
  }

  const content =
    `<div class="starforged-companion-card">` +
    // The name is the location Actor's — GM-edited free text — escaped as the
    // first-look line beside it is (issue #331 X45).
    `<h3>◈ Site Discovered — ${escapeSiteHtml(site.name)}</h3>` +
    `<p>A passage opens through to a ${kind} in the sector's outer reaches. ` +
    `It is now charted on the sector map — undertake an expedition there, or ` +
    `Explore a Waypoint to move through its zones.</p>` +
    firstLookLine +
    `</div>`;
  try {
    await ChatMessage.create({
      content,
      flags: { [MODULE_ID]: { siteDiscovered: true, siteId: site.id, siteType: site.type } },
    });
  } catch (err) {
    console.warn(`${MODULE_ID} | postSiteDiscoveryCard failed:`, err?.message ?? err);
  }
}

/**
 * Mark a DISCOVERED site fully explored (SITE-NO-COMPLETION fix, 2026-07):
 * sets the location Actor's status to "cleared" and stamps the discovery
 * record, closing the unexplored → visited → cleared lifecycle the schema
 * always documented. Same matching ladder as revealSectorSite (across every
 * sector at once — issue #300 F07), over discovered sites that aren't already
 * cleared. GM-gated by the caller.
 *
 * @param {string|null} label
 * @param {Object} [opts] — same injection seams as revealSectorSite
 * @returns {Promise<{sector:Object, site:Object}|null>}
 */
export async function clearSectorSite(label, opts = {}) {
  const getState  = opts.getState  ?? storedState;
  const setState  = opts.setState  ?? null;   // the store, on the write chain
  const updateLoc = opts.updateLoc ?? updateLocation;

  const state = getState();
  const found = selectSectorSite(state?.sectors, label, {
    eligible:       (site) => site.discovered && !site.cleared,
    activeSectorId: state?.activeSectorId ?? null,
    siteName:       siteDisplayName,
  });
  if (!found) return null;
  const { sector, site: record } = found;

  // On a copy, as revealSectorSite (issue #326 W51).
  const cleared = { ...record, cleared: true, name: siteDisplayName(record) };
  if (record.actorId) {
    try { await updateLoc(record.actorId, { status: "cleared" }); }
    catch (err) { console.warn(`${MODULE_ID} | clearSectorSite: location status update failed:`, err?.message ?? err); }
  }
  await persistSiteFlag(getState, setState, sector, record, "cleared", "clearSectorSite");
  return { sector, site: cleared };
}

/**
 * Persist one discovery record's flag onto the state as it is NOW (issue
 * #321 U06c): getState() is read again after the location write and the
 * scene restyle, and the flag set on a copy of it — copied along the path to
 * the record, never changed in place. Writing back the state read before
 * those awaits reverted whatever landed meanwhile: a player's relayed X-Card,
 * Take a Break, a `!bond` (rules/reachability.md §9). The record is found by
 * identity, else by its sector's and its own id; when the site is no longer
 * stored, nothing is written. A refused write rejects (the caller reports it)
 * and leaves the stored state as it was — nothing is set on it beforehand.
 *
 * @param {Function} getState — the injected seam's (unused with no setState: the store's)
 * @param {Function|null} setState — null for the stored campaignState
 * @param {Object}   sector — the sector the record was found in
 * @param {Object}   site   — the discovery record
 * @param {"discovered"|"cleared"} key
 * @param {string}   label  — for the log
 * @returns {Promise<void>}
 */
async function persistSiteFlag(getState, setState, sector, site, key, label) {
  // With no setState seam the flag goes to the store: read and written at its
  // turn on the client's campaignState write chain (CAMPSTATE-CHAIN-REST).
  if (!setState) {
    return serialiseCampaignStateWrite(async () => {
      const next = withSiteFlag(storedState(), sector, site, key, label);
      if (next) await game.settings.set(MODULE_ID, "campaignState", next);
    }, label);
  }
  const next = withSiteFlag(getState(), sector, site, key, label);
  if (next) await setState(next);
  return undefined;
}

/** The state with the site's flag set — a copy — or null when the site is no longer stored. */
function withSiteFlag(latest, sector, site, key, label) {
  const sameSector = (s) => s === sector || (sector?.id != null && s?.id === sector.id);
  const sameSite   = (d) => d === site   || (site?.id   != null && d?.id === site.id);
  let found = false;
  const sectors = (Array.isArray(latest?.sectors) ? latest.sectors : []).map((s) => {
    const discoveries = s?.mapData?.discoveries;
    if (!sameSector(s) || !Array.isArray(discoveries)) return s;
    return {
      ...s,
      mapData: {
        ...s.mapData,
        discoveries: discoveries.map((d) => {
          if (!sameSite(d)) return d;
          found = true;
          return { ...d, [key]: true };
        }),
      },
    };
  });
  if (!found) {
    console.warn(`${MODULE_ID} | ${label}: "${site?.name ?? site?.id}" is no longer stored — not saved.`);
    return null;
  }
  return { ...latest, sectors };
}

/** The stored campaignState (this client's cached value). */
function storedState() {
  return game.settings.get(MODULE_ID, "campaignState");
}

function escapeSiteHtml(s) {
  return String(s ?? "")
    .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");
}
